:root {
  /* Phase 5 theming: Guide overwrites these from docs/report.md preferences */
  --brand-name: "Apex Awards";
  --brand-bg: #071a36;
  --brand-surface: #ffffff;
  --brand-ink: #10233f;
  --brand-muted: #5a6d84;
  --brand-accent: #e7b83f;
  --brand-accent-2: #8ca9c9;
  --brand-sidebar: #0b2347;
  --brand-sidebar-text: #c7d6e8;
  --brand-font-display: "Manrope", "Segoe UI", sans-serif;
  --brand-font-body: "Manrope", "Segoe UI", sans-serif;
  --brand-radius: 0.45rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--brand-font-body);
  color: var(--brand-ink);
  background: var(--brand-bg);
}

.brand-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.35em;
  font-family: var(--brand-font-display);
  font-weight: 800;
  letter-spacing: -0.04em;
}

.brand-wordmark::before {
  content: "★";
  color: var(--brand-accent);
  font-size: 0.62em;
  line-height: 1;
}

/* —— Public landing —— */
.landing {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  color: var(--brand-surface);
  background:
    linear-gradient(135deg, rgba(231, 184, 63, 0.12), transparent 36%),
    linear-gradient(180deg, #123664 0%, var(--brand-bg) 72%);
  position: relative;
  overflow: hidden;
}

.landing::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(
      -28deg,
      transparent,
      transparent 56px,
      rgba(255, 255, 255, 0.045) 56px,
      rgba(255, 255, 255, 0.045) 58px
    );
  pointer-events: none;
}

.landing-nav,
.landing-hero,
.landing-foot {
  position: relative;
  z-index: 1;
}

.landing-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem clamp(1.25rem, 4vw, 3rem);
}

.landing-nav .brand-wordmark {
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  color: var(--brand-surface);
  text-decoration: none;
}

.landing-nav-actions {
  display: flex;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.landing-hero {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(2rem, 8vh, 5rem) clamp(1.25rem, 4vw, 3rem) 3rem;
  max-width: 42rem;
}

.landing-kicker {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--brand-accent);
  margin: 0 0 1rem;
}

.landing-hero .brand-wordmark {
  font-size: clamp(3rem, 9vw, 5.5rem);
  line-height: 0.95;
  margin: 0 0 1.25rem;
  color: var(--brand-surface);
}

.landing-lead {
  font-size: clamp(1.05rem, 2.2vw, 1.25rem);
  line-height: 1.55;
  color: color-mix(in srgb, var(--brand-surface) 82%, transparent);
  margin: 0 0 2rem;
  max-width: 28rem;
}

.landing-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.btn-landing {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.35rem;
  border-radius: 999px;
  font-weight: 600;
  text-decoration: none;
  border: 1.5px solid transparent;
  transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.btn-landing:hover {
  transform: translateY(-1px);
}

.btn-landing-primary {
  background: var(--brand-accent);
  color: var(--brand-ink);
}

.btn-landing-primary:hover {
  background: color-mix(in srgb, var(--brand-accent) 82%, #fff);
  color: var(--brand-ink);
}

.btn-landing-ghost {
  background: transparent;
  color: var(--brand-surface);
  border-color: color-mix(in srgb, var(--brand-surface) 45%, transparent);
}

.btn-landing-ghost:hover {
  border-color: var(--brand-surface);
  background: color-mix(in srgb, var(--brand-surface) 8%, transparent);
  color: var(--brand-surface);
}

.landing-foot {
  padding: 1.25rem clamp(1.25rem, 4vw, 3rem) 1.75rem;
  font-size: 0.85rem;
  color: color-mix(in srgb, var(--brand-surface) 45%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .btn-landing:hover {
    transform: none;
  }
}

/* —— Auth —— */
.auth-shell {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  background:
    linear-gradient(135deg, rgba(231, 184, 63, 0.12), transparent 34%),
    linear-gradient(180deg, #123664 0%, var(--brand-bg) 100%);
}

.auth-panel {
  width: min(420px, 100%);
  background: var(--brand-surface);
  color: var(--brand-ink);
  border-radius: var(--brand-radius);
  padding: 2rem 1.75rem;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.28);
}

.auth-panel .brand-wordmark {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
  color: var(--brand-accent);
}

.auth-panel .auth-tagline {
  color: var(--brand-muted);
  margin-bottom: 1.5rem;
}

.auth-panel .btn-primary {
  background: var(--brand-accent);
  border-color: var(--brand-accent);
}

.auth-panel .btn-primary:hover {
  background: color-mix(in srgb, var(--brand-accent) 82%, #fff);
  border-color: color-mix(in srgb, var(--brand-accent) 82%, #fff);
}

.auth-panel .btn-outline-secondary {
  color: var(--brand-ink);
  border-color: color-mix(in srgb, var(--brand-ink) 25%, transparent);
}

.auth-back {
  display: inline-block;
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: var(--brand-muted);
  text-decoration: none;
}

.auth-back:hover {
  color: var(--brand-accent);
}

{% extends "base.html" %}

{% block internal_css %}
<style>
    body {
        overflow-x: hidden;
        background: #f4f6f8;
    }

    #wrapper {
        display: flex;
        min-height: 100vh;
    }

    #sidebar {
        min-width: 250px;
        max-width: 250px;
        min-height: 100vh;
        transition: all 0.3s;
        background: var(--brand-sidebar);
        color: #fff;
    }

    #sidebar.collapsed {
        margin-left: -250px;
    }

    #sidebar .nav-link {
        color: var(--brand-sidebar-text);
        font-weight: 500;
    }

    #sidebar .nav-link:hover,
    #sidebar .nav-link.active {
        color: #fff;
        background-color: color-mix(in srgb, var(--brand-accent) 55%, #000);
        border-radius: 0.5rem;
    }

    #sidebar .brand-wordmark {
        color: #fff;
        font-size: 1.25rem;
        text-align: center;
        margin: 1rem 0 1.5rem;
    }

    #content {
        width: 100%;
        padding: 1rem;
        transition: all 0.3s;
        display: flex;
        flex-direction: column;
        background-color: #f4f6f8;
    }

    .navbar {
        border-bottom: 1px solid #dee2e6;
    }
</style>
{% block additional_styles %}{% endblock %}
{% endblock %}

{% block content %}
<div id="wrapper">
    <nav id="sidebar" class="p-3 d-flex flex-column vh-100">
        <div class="brand-wordmark">Apex Awards</div>

        <ul class="nav nav-pills flex-column gap-2 flex-grow-1">
            <li class="nav-item">
                <a class="nav-link d-flex align-items-center {{ 'active' if request.url.path.startswith('/app') }}"
                   href="{{ url_for('user_home_view') }}">
                    <span class="material-symbols-outlined me-2">home</span>
                    Home
                </a>
            </li>
            <li class="nav-item mt-auto">
                <a class="nav-link d-flex align-items-center text-danger" href="{{ url_for('logout') }}">
                    <span class="material-symbols-outlined me-2">logout</span>
                    Logout
                </a>
            </li>
        </ul>
    </nav>

    <div id="content">
        <nav class="navbar navbar-expand-lg bg-white mb-4 px-3 rounded-3 shadow-sm">
            <button class="btn btn-outline-secondary" id="menu-toggle" type="button">
                <span class="material-symbols-outlined md-dark">menu</span>
            </button>
            <div class="ms-auto d-flex align-items-center gap-3">
                <span class="fw-semibold">Welcome, {{ user.username }}</span>
            </div>
        </nav>

        <div class="row">
            <div class="col-12">
                {% for message in get_flashed_messages(request) %}
                <div class="alert alert-{{ message.type }}" role="alert">{{ message.message }}</div>
                {% endfor %}
            </div>
        </div>

        {% block subpage_content %}{% endblock %}
    </div>
</div>

<script>
    document.getElementById("menu-toggle").addEventListener("click", function () {
        document.getElementById("sidebar").classList.toggle("collapsed");
    });
</script>
{% block subpage_scripts %}{% endblock %}
{% endblock %}

