{% block internal_css %}
<style>
    body {
        overflow-x: hidden;
        background: #f4f6f8;
    }

    .student-shell {
        min-height: 100vh;
    }

    .student-header {
        display: flex;
        align-items: center;
        gap: 1.5rem;
        min-height: 76px;
        padding: 0.75rem clamp(1rem, 3vw, 3rem);
        background: var(--brand-surface);
        border-bottom: 1px solid #d8e0e9;
    }

    .student-header .brand-wordmark {
        flex: 0 0 auto;
        color: var(--brand-ink);
        font-size: 1.35rem;
        text-decoration: none;
    }

    .student-nav {
        display: flex;
        align-items: stretch;
        gap: 0.3rem;
        margin-left: 0.5rem;
    }

    .student-nav-link {
        display: inline-flex;
        align-items: center;
        min-height: 42px;
        padding: 0.55rem 0.8rem;
        border: 1px solid transparent;
        color: var(--brand-ink);
        font-size: 0.88rem;
        text-decoration: none;
        white-space: nowrap;
    }

    .student-nav-link:hover,
    .student-nav-link.active {
        background: color-mix(in srgb, var(--brand-accent) 25%, #fff);
        border-color: color-mix(in srgb, var(--brand-accent) 60%, #fff);
        color: var(--brand-ink);
    }

    .student-nav-link-muted {
        color: var(--brand-muted);
    }

    .student-user {
        display: flex;
        align-items: center;
        gap: 0.65rem;
        margin-left: auto;
        white-space: nowrap;
    }

    .student-badge {
        display: inline-grid;
        place-items: center;
        width: 34px;
        height: 34px;
        border: 1px solid #aebdcd;
        border-radius: 50%;
        background: #f4f6f8;
        font-size: 0.8rem;
        font-weight: 800;
    }

    .student-main {
        width: 100%;
        padding: clamp(1.25rem, 3vw, 2.5rem) clamp(1rem, 3vw, 3rem);
        background-color: #f4f6f8;
    }

    @media (max-width: 900px) {
        .student-header {
            flex-wrap: wrap;
        }

        .student-nav {
            order: 3;
            width: 100%;
            overflow-x: auto;
            margin-left: 0;
        }

        .student-user {
            margin-left: auto;
        }
    }
</style>
{% block additional_styles %}{% endblock %}
{% endblock %}

{% block content %}
<div class="student-shell">
    <header class="student-header">
        <a class="brand-wordmark" href="{{ url_for('user_home_view') }}">Apex Awards</a>
        <nav class="student-nav" aria-label="Student navigation">
            <a class="student-nav-link {{ 'active' if request.url.path == '/app' }}" href="{{ url_for('user_home_view') }}">Student home</a>
            <a class="student-nav-link {{ 'active' if request.url.path.startswith('/app/volunteer-hours') }}" href="{{ url_for('volunteer_hours_view') }}">Submit hours</a>
            <span class="student-nav-link student-nav-link-muted">Leaderboard &amp; milestones</span>
            <span class="student-nav-link student-nav-link-muted">Prizes &amp; redemptions</span>
        </nav>
        <div class="student-user">
            <span class="student-badge">{{ user.username[:1]|upper }}</span>
            <span class="fw-semibold">{{ user.username }}</span>
            <a class="btn btn-outline-secondary btn-sm" href="{{ url_for('logout') }}">Sign out</a>
        </div>
    </header>

    <main class="student-main">
        {% for message in get_flashed_messages(request) %}
        <div class="alert alert-{{ message.type }}" role="alert">{{ message.message }}</div>
        {% endfor %}
        {% block subpage_content %}{% endblock %}
    </main>
</div>
{% block subpage_scripts %}{% endblock %}
{% endblock %}

{% extends "authenticated-base.html" %}
{% block title %}Volunteer Hours{% endblock %}

{% block additional_styles %}
<style>
  .workflow-heading {
    margin-bottom: 1.5rem;
  }

  .workflow-heading h1 {
    font-size: clamp(1.7rem, 3vw, 2.2rem);
    font-weight: 800;
  }

  .volunteer-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.7fr) minmax(280px, 0.8fr);
    gap: 1.25rem;
    align-items: start;
  }

  .wire-card {
    background: var(--brand-surface);
    border: 1px solid #b8c3cf;
    box-shadow: none;
  }

  .wire-card-header {
    padding: 1.15rem 1.25rem;
    border-bottom: 1px solid #d8e0e9;
  }

  .wire-card-body {
    padding: 1.25rem;
  }

  .proof-dropzone {
    display: block;
    padding: 1.5rem;
    border: 1px dashed #8da0b5;
    background: #f4f6f8;
    text-align: center;
  }

  .pending-item {
    padding: 0.85rem 0;
    border-bottom: 1px solid #d8e0e9;
  }

  .pending-item:last-child {
    border-bottom: 0;
    padding-bottom: 0;
  }

  .status-text {
    font-size: 0.82rem;
    font-weight: 700;
  }

  @media (max-width: 900px) {
    .volunteer-layout {
      grid-template-columns: 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="workflow-heading">
  <h1 class="mb-1">Submit hours</h1>
  <p class="text-muted mb-0">Log completed volunteer work. Hours count toward your rewards once approved.</p>
</div>

<div class="volunteer-layout">
  <section id="submit-hours" class="wire-card">
    <div class="wire-card-header">
      <h2 class="h5 mb-1">New volunteer-hour submission</h2>
      <p class="text-muted small mb-0">Required fields are marked with <span class="required-mark">*</span></p>
    </div>
    <div class="wire-card-body">
      <form method="post" action="{{ request.url.path }}" enctype="multipart/form-data">
        <div class="row g-3">
          <div class="col-12">
            <label class="form-label" for="event_name">Event name <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_name" name="event_name" placeholder="Volunteer activity" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="hours">Hours <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="hours" name="hours" type="number" min="0.01" step="0.01" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="event_date">Event date <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_date" name="event_date" type="date" max="{{ today }}" required>
          </div>
          <div class="col-12">
            <label class="form-label" for="additional_info">Additional information <span class="text-muted">(optional)</span></label>
            <textarea class="form-control" id="additional_info" name="additional_info" rows="3" placeholder="Add any extra context, notes, or details about the activity."></textarea>
          </div>
          <div class="col-12">
            <label class="form-label" for="proof">Proof <span class="required-mark" aria-hidden="true">*</span></label>
            <label class="proof-dropzone" for="proof">
              <strong>Drop a file here or browse files</strong>
              <span class="d-block text-muted small mt-2">Photo or signed attendance sheet · JPG, PNG · Max 10 MB</span>
            </label>
            <input class="visually-hidden" id="proof" name="proof" type="file" accept="image/*" required>
            <div class="text-muted small mt-2">Upload proof before submitting.</div>
          </div>
        </div>
        <div class="d-flex flex-wrap gap-2 mt-4">
          <button class="btn btn-primary" type="submit">Submit</button>
          <a class="btn btn-outline-secondary" href="{{ url_for('user_home_view') }}">Cancel</a>
        </div>
      </form>
    </div>
  </section>

  <aside class="d-grid gap-3">
    <section class="wire-card">
      <div class="wire-card-body">
        <h2 class="h6 mb-2">Tip: make your proof easy to verify</h2>
        <p class="small text-muted mb-0">Include your name, event date, and volunteered hours in a clear proof image.</p>
      </div>
    </section>

    <section class="wire-card">
      <div class="wire-card-header">
        <h2 class="h6 mb-0">Your submissions</h2>
      </div>
      <div class="wire-card-body">
        {% if logs %}
        {% for log in logs %}
        <div class="pending-item">
          <div class="fw-semibold">{{ log.event_name }}</div>
          <div class="small text-muted">{{ log.hours }} hours · {{ log.event_date.strftime('%b %d, %Y') }}</div>
          <div class="status-text mt-1">{{ log.status|title }}</div>
          {% if log.status == 'rejected' and log.rejection_reason %}
          <div class="small text-danger mt-1">{{ log.rejection_reason }}</div>
          {% endif %}
        </div>
        {% endfor %}
        {% else %}
        <p class="small text-muted mb-0">No submissions yet.</p>
        {% endif %}
      </div>
    </section>
  </aside>
  </div>
{% endblock %}

