{% extends "authenticated-base.html" %}
{% block title %}Volunteer Hours{% endblock %}

{% block additional_styles %}
<style>
  .workflow-heading {
    margin-bottom: 1.5rem;
  }

  .workflow-heading h1 {
    font-size: clamp(1.7rem, 3vw, 2.2rem);
    font-weight: 800;
  }

  .volunteer-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.7fr) minmax(280px, 0.8fr);
    gap: 1.25rem;
    align-items: start;
  }

  .wire-card {
    background: var(--brand-surface);
    border: 1px solid #b8c3cf;
    box-shadow: none;
  }

  .wire-card-header {
    padding: 1.15rem 1.25rem;
    border-bottom: 1px solid #d8e0e9;
  }

  .wire-card-body {
    padding: 1.25rem;
  }

  .proof-dropzone {
    display: block;
    padding: 1.5rem;
    border: 1px dashed #8da0b5;
    background: #f4f6f8;
    text-align: center;
    cursor: pointer;
  }

  .proof-dropzone:hover,
  .proof-dropzone:has(+ input:focus) {
    border-color: var(--brand-accent);
    background: color-mix(in srgb, var(--brand-accent) 10%, #f4f6f8);
  }

  .proof-preview {
    display: none;
    width: 100%;
    max-height: 180px;
    margin-top: 0.9rem;
    object-fit: contain;
    border: 1px solid #b8c3cf;
    background: #fff;
  }

  .pending-item {
    padding: 0.85rem 0;
    border-bottom: 1px solid #d8e0e9;
  }

  .pending-item:last-child {
    border-bottom: 0;
    padding-bottom: 0;
  }

  .status-text {
    font-size: 0.82rem;
    font-weight: 700;
  }

  @media (max-width: 900px) {
    .volunteer-layout {
      grid-template-columns: 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="workflow-heading">
  <h1 class="mb-1">Submit hours</h1>
  <p class="text-muted mb-0">Log completed volunteer work. Hours count toward your rewards once approved.</p>
</div>

<div class="volunteer-layout">
  <section id="submit-hours" class="wire-card">
    <div class="wire-card-header">
      <h2 class="h5 mb-1">New volunteer-hour submission</h2>
      <p class="text-muted small mb-0">Required fields are marked with <span class="required-mark">*</span></p>
    </div>
    <div class="wire-card-body">
      <form method="post" action="{{ request.url.path }}" enctype="multipart/form-data">
        <div class="row g-3">
          <div class="col-12">
            <label class="form-label" for="event_name">Event name <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_name" name="event_name" placeholder="Volunteer activity" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="hours">Hours <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="hours" name="hours" type="number" min="0.01" step="0.01" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="event_date">Event date <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_date" name="event_date" type="date" max="{{ today }}" required>
          </div>
          <div class="col-12">
            <label class="form-label" for="additional_info">Additional information <span class="text-muted">(optional)</span></label>
            <textarea class="form-control" id="additional_info" name="additional_info" rows="3" placeholder="Add any extra context, notes, or details about the activity."></textarea>
          </div>
          <div class="col-12">
            <label class="form-label" for="proof">Proof <span class="required-mark" aria-hidden="true">*</span></label>
            <label class="proof-dropzone" for="proof">
              <strong>Drop a file here or browse files</strong>
              <span class="d-block text-muted small mt-2">Photo or signed attendance sheet · JPG, PNG · Max 10 MB</span>
            </label>
            <input class="visually-hidden" id="proof" name="proof" type="file" accept="image/*" required>
            <img class="proof-preview" id="proof-preview" alt="Selected proof preview">
            <div class="text-muted small mt-2" id="proof-status">No image selected yet.</div>
          </div>
        </div>
        <div class="d-flex flex-wrap gap-2 mt-4">
          <button class="btn btn-primary" type="submit">Submit</button>
          <a class="btn btn-outline-secondary" href="{{ url_for('user_home_view') }}">Cancel</a>
        </div>
      </form>
    </div>
  </section>

  <aside class="d-grid gap-3">
    <section class="wire-card">
      <div class="wire-card-body">
        <h2 class="h6 mb-2">Tip: make your proof easy to verify</h2>
        <p class="small text-muted mb-0">Include your name, event date, and volunteered hours in a clear proof image.</p>
      </div>
    </section>

    <section class="wire-card">
      <div class="wire-card-header">
        <h2 class="h6 mb-0">Your submissions</h2>
      </div>
      <div class="wire-card-body">
        {% if logs %}
        {% for log in logs %}
        {% if log.status != 'rejected' %}
        <div class="pending-item">
          <div class="fw-semibold">{{ log.event_name }}</div>
          <div class="small text-muted">{{ log.hours }} hours · {{ log.event_date.strftime('%b %d, %Y') }}</div>
          <div class="status-text mt-1">{{ log.status|title }}</div>
        </div>
        {% endif %}
        {% endfor %}
        {% else %}
        <p class="small text-muted mb-0">No submissions yet.</p>
        {% endif %}
      </div>
    </section>

    <section class="wire-card">
      <div class="wire-card-header">
        <h2 class="h6 mb-0">Rejected submissions</h2>
      </div>
      <div class="wire-card-body">
        {% set rejected = namespace(found=false) %}
        {% for log in logs %}
        {% if log.status == 'rejected' %}
        {% set rejected.found = true %}
        <div class="pending-item">
          <div class="fw-semibold">{{ log.event_name }}</div>
          <div class="small text-muted">{{ log.hours }} hours · {{ log.event_date.strftime('%b %d, %Y') }}</div>
          <div class="status-text text-danger mt-1">Rejected</div>
          {% if log.rejection_reason %}<div class="small text-muted mt-1">{{ log.rejection_reason }}</div>{% endif %}
        </div>
        {% endif %}
        {% endfor %}
        {% if not rejected.found %}<p class="small text-muted mb-0">No rejected submissions.</p>{% endif %}
      </div>
    </section>
  </aside>
  </div>
{% endblock %}

{% block subpage_scripts %}
<script>
  const proofInput = document.getElementById("proof");
  const proofPreview = document.getElementById("proof-preview");
  const proofStatus = document.getElementById("proof-status");

  proofInput.addEventListener("change", function () {
    const file = proofInput.files[0];
    if (!file) {
      proofPreview.style.display = "none";
      proofPreview.removeAttribute("src");
      proofStatus.textContent = "No image selected yet.";
      return;
    }

    proofPreview.src = URL.createObjectURL(file);
    proofPreview.style.display = "block";
    proofStatus.textContent = `Selected: ${file.name}`;
  });
</script>
{% endblock %}

from sqlmodel import Session, select

from app.models.volunteer_log import VolunteerLog


class VolunteerLogRepository:
    def __init__(self, db: Session):
        self.db = db

    def get_by_user_id(self, user_id: int) -> list[VolunteerLog]:
        statement = (
            select(VolunteerLog)
            .where(VolunteerLog.user_id == user_id)
            .order_by(VolunteerLog.submitted_at.desc())
        )
        return list(self.db.exec(statement).all())

    def create(self, volunteer_log: VolunteerLog) -> VolunteerLog:
        self.db.add(volunteer_log)
        self.db.commit()
        self.db.refresh(volunteer_log)
        return volunteer_log

    def get_pending(self) -> list[VolunteerLog]:
        statement = (
            select(VolunteerLog)
            .where(VolunteerLog.status == "pending")
            .order_by(VolunteerLog.submitted_at.asc())
        )
        return list(self.db.exec(statement).all())

    def get_approved(self) -> list[VolunteerLog]:
        statement = select(VolunteerLog).where(VolunteerLog.status == "approved")
        return list(self.db.exec(statement).all())

    def update_status(
        self,
        log_id: int,
        status: str,
        rejection_reason: str | None = None,
    ) -> VolunteerLog:
        volunteer_log = self.db.get(VolunteerLog, log_id)
        if volunteer_log is None:
            raise ValueError("Volunteer log not found.")
        volunteer_log.status = status
        volunteer_log.rejection_reason = rejection_reason
        self.db.add(volunteer_log)
        self.db.commit()
        self.db.refresh(volunteer_log)
        return volunteer_log

from datetime import date, datetime
from pathlib import Path
from uuid import uuid4

from fastapi import UploadFile

from app.models.volunteer_log import VolunteerLog
from app.repositories.volunteer_log import VolunteerLogRepository
from app.repositories.user import UserRepository


class VolunteerHoursService:
    MILESTONES = (
        {"title": "Bronze", "badge": "Bronze", "required_hours": 25},
        {"title": "Silver", "badge": "Silver", "required_hours": 50},
        {"title": "Gold", "badge": "Gold", "required_hours": 100},
    )

    def __init__(self, db):
        self.volunteer_log_repo = VolunteerLogRepository(db)
        self.user_repo = UserRepository(db)

    def get_student_logs(self, user_id: int):
        return self.volunteer_log_repo.get_by_user_id(user_id)

    async def submit_student_log(
        self,
        user_id: int,
        event_name: str,
        hours: float,
        event_date: date,
        additional_info: str | None,
        proof: UploadFile,
    ) -> VolunteerLog:
        if hours <= 0:
            raise ValueError("Hours must be greater than 0.")
        if event_date > date.today():
            raise ValueError("Event date cannot be in the future.")
        if not proof.content_type or not proof.content_type.startswith("image/"):
            raise ValueError("Proof must be an image file.")

        upload_dir = Path("app/static/uploads")
        upload_dir.mkdir(parents=True, exist_ok=True)
        suffix = Path(proof.filename or "proof").suffix.lower()
        filename = f"{uuid4().hex}{suffix}"
        upload_path = upload_dir / filename
        upload_path.write_bytes(await proof.read())

        volunteer_log = VolunteerLog(
            user_id=user_id,
            event_name=event_name.strip(),
            hours=hours,
            event_date=event_date,
            submitted_at=datetime.utcnow(),
            proof=f"uploads/{filename}",
            additional_info=additional_info.strip() if additional_info else None,
        )
        return self.volunteer_log_repo.create(volunteer_log)

    def get_pending_submissions(self) -> list[dict]:
        submissions = []
        for volunteer_log in self.volunteer_log_repo.get_pending():
            student = self.user_repo.get_by_id(volunteer_log.user_id)
            submissions.append(
                {
                    "log": volunteer_log,
                    "student_name": student.username if student else "Unknown student",
                }
            )
        return submissions

    def approve_submission(self, log_id: int) -> None:
        self.volunteer_log_repo.update_status(log_id, "approved")

    def reject_submission(self, log_id: int, rejection_reason: str) -> None:
        reason = rejection_reason.strip()
        if not reason:
            raise ValueError("A rejection reason is required.")
        self.volunteer_log_repo.update_status(log_id, "rejected", reason)

    def get_progress(self, user_id: int) -> dict:
        approved_hours = sum(
            log.hours
            for log in self.volunteer_log_repo.get_by_user_id(user_id)
            if log.status == "approved"
        )
        milestones = []
        for milestone in self.MILESTONES:
            required_hours = milestone["required_hours"]
            milestones.append(
                {
                    **milestone,
                    "achieved": approved_hours >= required_hours,
                    "percent": min(100, round(approved_hours / required_hours * 100)),
                }
            )
        return {"approved_hours": approved_hours, "milestones": milestones}

    def get_leaderboard(self, user_id: int) -> list[dict]:
        totals: dict[int, float] = {}
        for log in self.volunteer_log_repo.get_approved():
            totals[log.user_id] = totals.get(log.user_id, 0) + log.hours

        leaderboard = []
        for student in self.user_repo.get_all_users():
            leaderboard.append(
                {
                    "user_id": student.id,
                    "username": student.username,
                    "hours": totals.get(student.id, 0),
                    "is_current_user": student.id == user_id,
                }
            )
        leaderboard.sort(key=lambda entry: (-entry["hours"], entry["username"].lower()))
        for rank, entry in enumerate(leaderboard, start=1):
            entry["rank"] = rank
        return leaderboard

