      {% if prize.stock <= 0 %}
      <button class="btn btn-outline-secondary mt-auto" type="button" disabled>Out of stock</button>
      {% elif spendable_balance < prize.hours_cost %}
      <button class="btn btn-outline-secondary mt-auto" type="button" disabled>Not enough hours</button>
      {% else %}
      <button class="btn btn-primary mt-auto redeem-button" type="button" data-bs-toggle="modal" data-bs-target="#redemptionModal" data-prize-name="{{ prize.name }}" data-prize-cost="{{ prize.hours_cost|round(2) }}" data-prize-image="{{ url_for('static', path=prize.image_url) }}" data-redeem-url="{{ url_for('redeem_prize', prize_id=prize.prize_id) }}">Redeem</button>
      {% endif %}
    </div>
  </article>
  {% endfor %}
</div>

<div class="redemption-layout">
  <section class="wire-card redemption-history">
