  }

  .admin-table {
    width: 100%;
    margin: 0;
  }

  .admin-table th,
  .admin-table td {
    padding: 0.75rem;
    border-bottom: 1px solid #d8e0e9;
    vertical-align: middle;
  }

  .admin-table th {
    background: #e8ebee;
