    background: #176b2b;
    border-color: #176b2b;
    color: #fff;
  }

  .btn-admin-reject {
    background: #c93636;
    border-color: #c93636;
    color: #fff;
  }

  .btn-admin-reject:hover,
  .btn-admin-reject:focus {
    background: #9f2525;
    border-color: #9f2525;
    color: #fff;
  }

