{% block admin_content %}
<div class="admin-heading-row">
  <div>
    <h1 class="h2 mb-1">Admin Console</h1>
    <p class="text-muted mb-0">Review volunteer-hour submissions and manage prize pickups.</p>
  </div>
  <div class="admin-actions"><button class="btn btn-outline-secondary" type="button" onclick="window.location.reload()">Refresh</button></div>
</div>

<div class="admin-stat-grid">
  <div class="admin-stat"><span class="text-muted small">Pending submissions</span><strong>{{ stats.pending_submissions }} submissions</strong></div>
  <div class="admin-stat"><span class="text-muted small">Out of stock prizes</span><strong>{{ stats.out_of_stock_prizes }} prize{{ '' if stats.out_of_stock_prizes == 1 else 's' }}</strong></div>
  <div class="admin-stat"><span class="text-muted small">Pending redemptions</span><strong>{{ stats.pending_redemptions }} redemption{{ '' if stats.pending_redemptions == 1 else 's' }}</strong></div>
  <div class="admin-stat"><span class="text-muted small">Student volunteers</span><strong>{{ stats.student_volunteers }} volunteers</strong></div>
</div>

<div class="admin-queues">
  <section class="admin-queue">
    <div class="admin-queue-header">
      <h2 class="h5 mb-1">Pending volunteer-hour submissions ({{ submissions|length }})</h2>
      <p class="text-muted small mb-0">Rejection requires a brief explanation for the student.</p>
    </div>
    {% if submissions %}
    <div class="table-responsive">
      <table class="admin-table">
        <thead><tr><th>Student name</th><th>Submitted</th><th>Event</th><th>Hours</th><th>View proof</th><th>Approve</th><th>Reject</th></tr></thead>
        <tbody>
        {% for submission in submissions %}
        <tr>
          <td class="fw-semibold">{{ submission.student_name }}</td>
          <td>{{ submission.log.submitted_at.strftime('%b %d, %Y') }}</td>
          <td>{{ submission.log.event_name }}</td>
          <td>{{ submission.log.hours }}</td>
          <td><a class="btn btn-outline-secondary btn-sm" href="{{ url_for('static', path=submission.log.proof) }}" target="_blank" rel="noopener">View proof</a></td>
          <td><form method="post" action="{{ url_for('approve_volunteer_hours', log_id=submission.log.log_id) }}"><button class="btn btn-admin-approve btn-sm" type="submit">Approve</button></form></td>
          <td><button class="btn btn-admin-reject btn-sm reject-button" type="button" data-bs-toggle="modal" data-bs-target="#rejectModal" data-reject-url="{{ url_for('reject_volunteer_hours', log_id=submission.log.log_id) }}" data-student-name="{{ submission.student_name }}">Reject</button></td>
        </tr>
        {% endfor %}
        </tbody>
      </table>
    </div>
    {% else %}<p class="text-muted p-3 mb-0">No pending volunteer-hour submissions.</p>{% endif %}
  </section>

  <section class="admin-queue">
    <div class="admin-queue-header">
      <h2 class="h5 mb-1">Pending prize redemptions ({{ prize_fulfilments|length }})</h2>
      <p class="text-muted small mb-0">Mark fulfilled after the student collects their prize.</p>
    </div>
    {% if prize_fulfilments %}
    <div class="table-responsive">
      <table class="admin-table">
        <thead><tr><th>Student name</th><th>Prize name</th><th>Delivery type</th><th>Submitted</th><th>Fulfilment</th></tr></thead>
        <tbody>
        {% for item in prize_fulfilments %}
        <tr>
          <td class="fw-semibold">{{ item.student_name }}</td>
          <td>{{ item.prize_name }}</td>
          <td>Manual</td>
          <td>{{ item.redemption.redeemed_at.strftime('%b %d, %Y') }}</td>
          <td><form method="post" action="{{ url_for('fulfill_prize_redemption', redemption_id=item.redemption.redemption_id) }}"><button class="btn btn-primary btn-sm" type="submit">Mark fulfilled</button></form></td>
        </tr>
        {% endfor %}
        </tbody>
      </table>
    </div>
    {% else %}<p class="text-muted p-3 mb-0">No pending prize redemptions.</p>{% endif %}
  </section>
</div>

<div class="modal fade" id="rejectModal" tabindex="-1" aria-labelledby="rejectModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header"><h2 class="modal-title h5" id="rejectModalLabel">Reject submission</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div>
      <form id="rejectForm" method="post">
        <div class="modal-body">
          <p class="small text-muted">Enter the reason <span id="rejectStudentName"></span> needs to address.</p>
          <label class="visually-hidden" for="rejection_reason">Rejection reason</label>
          <textarea class="form-control" id="rejection_reason" name="rejection_reason" rows="4" placeholder="Enter the reason the student needs to address..." required></textarea>
        </div>
        <div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-admin-reject" type="submit">Confirm Reject</button></div>
      </form>
    </div>
  </div>
</div>
{% endblock %}

{% block subpage_scripts %}
<script>
  document.querySelectorAll(".reject-button").forEach(function (button) {
    button.addEventListener("click", function () {
      document.getElementById("rejectForm").action = button.dataset.rejectUrl;
      document.getElementById("rejectStudentName").textContent = `for ${button.dataset.studentName}`;
      document.getElementById("rejection_reason").value = "";
    });
  });
</script>
{% endblock %}

{% extends "authenticated-base.html" %}
{% block title %}Student Home{% endblock %}

{% block additional_styles %}
<style>
  .home-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(300px, 0.8fr);
    gap: 1.25rem;
  }

  .home-heading h1 {
    font-size: clamp(1.8rem, 3vw, 2.3rem);
    font-weight: 800;
  }

  .home-heading {
    margin-bottom: 1.25rem;
  }

  .home-stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .home-stat {
    padding: 1rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .home-stat strong {
    display: block;
    font-size: 1.55rem;
  }

  .home-section {
    margin-bottom: 1.25rem;
  }

  .home-milestone {
    padding: 1.25rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .home-badge-panel {
    padding: 1.25rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .home-badge-icon {
    display: grid;
    place-items: center;
    min-height: 90px;
    margin-top: 1rem;
    background: #e8ebee;
  }

  .home-badge-icon .material-symbols-outlined {
    color: var(--brand-accent);
    font-size: 3rem;
  }

  .home-leaderboard-row {
    display: grid;
    grid-template-columns: 2.5rem 1fr auto;
    gap: 0.75rem;
    padding: 0.75rem 0;
    border-bottom: 1px solid #d8e0e9;
  }

  .home-leaderboard-row:last-child {
    border-bottom: 0;
  }

  @media (max-width: 1100px) {
    .home-layout {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 850px) {
    .home-stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 500px) {
    .home-stats {
      grid-template-columns: 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="home-heading">
  <h1 class="mb-1">Welcome back, {{ user.username }}</h1>
  <p class="text-muted mb-0">Your volunteer activity, rewards, and progress at a glance.</p>
</div>

<div class="home-stats">
  <div class="home-stat"><span class="text-muted small">Lifetime hours</span><strong>{{ approved_hours|round(2) }} hours</strong><span class="small text-muted">Total approved volunteer hours</span></div>
  <div class="home-stat"><span class="text-muted small">Spendable balance</span><strong>{{ spendable_balance|round(2) }} hours</strong><span class="small text-muted">After redemptions</span></div>
  <div class="home-stat"><span class="text-muted small">Rank</span><strong>#{{ leaderboard.current_rank or '—' }}</strong><span class="small text-muted">Among {{ leaderboard.total_participants }} student volunteers</span></div>
  <div class="home-stat"><span class="text-muted small">Badges</span><strong>{{ progress.milestones|selectattr('achieved')|list|length }}/{{ progress.milestones|length }}</strong><span class="small text-muted">{{ badge.name }} milestone unlocked</span></div>
</div>

<div class="home-layout">
  <div>
    <section class="home-section home-milestone">
      <div class="d-flex justify-content-between align-items-center gap-2 mb-2">
        <h2 class="h5 mb-0">Next milestone: {{ next_milestone.title }}</h2>
        <strong>{{ progress.approved_hours|round(2) }} / {{ next_milestone.required_hours }} lifetime hours</strong>
      </div>
      <div class="progress" role="progressbar" aria-label="{{ next_milestone.title }} progress" aria-valuenow="{{ next_milestone.percent }}" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width: {{ next_milestone.percent }}%; background-color: var(--brand-accent);"></div></div>
      <p class="text-muted mb-0 mt-3">{{ next_milestone.remaining_hours|round(2) }} more approved hours to unlock {{ next_milestone.title }}. Redeeming prizes does not affect milestones.</p>
    </section>

    <section class="home-section wire-card">
      <div class="wire-card-header d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Recent submissions</h2><a class="btn btn-primary btn-sm" href="{{ url_for('volunteer_hours_view') }}">Submit hours</a></div>
      <div class="table-responsive">
        <table class="table align-middle mb-0">
          <thead><tr><th>Event name</th><th>Date submitted</th><th>Hours</th><th>Status</th><th>Details</th></tr></thead>
          <tbody>
          {% for log in logs[:5] %}
          <tr><td>{{ log.event_name }}</td><td>{{ log.submitted_at.strftime('%b %d, %Y') }}</td><td>{{ log.hours }}</td><td>{{ log.status|title }}</td><td><a href="{{ url_for('volunteer_hours_view') }}">View details</a></td></tr>
          {% else %}<tr><td colspan="5" class="text-muted">No submissions yet.</td></tr>{% endfor %}
          </tbody>
        </table>
      </div>
      <div class="small text-muted p-3 border-top">Pending and rejected hours are not included in your balance.</div>
    </section>
  </div>

  <div>
    <section class="home-section home-badge-panel">
      <h2 class="h5 mb-1">Latest badge</h2>
      <div class="text-uppercase text-muted small">{{ badge.name }} badge · {% if badge.name == 'No badge yet' %}locked{% else %}unlocked{% endif %}</div>
      <div class="home-badge-icon"><span class="material-symbols-outlined" aria-hidden="true">{{ badge.icon }}</span></div>
      {% if badge.reached_date %}<p class="text-muted small mt-3 mb-1">Reached {{ badge.reached_date.strftime('%b %d, %Y') }}.</p>{% endif %}
      <p class="small mb-0">Next: {{ next_milestone.title }} at {{ next_milestone.required_hours }} lifetime hours</p>
    </section>

    <section class="wire-card">
      <div class="wire-card-header"><h2 class="h5 mb-0">Top 3 volunteers</h2></div>
      <div class="p-3">
        {% for entry in leaderboard.entries[:3] %}
        <div class="home-leaderboard-row"><strong>#{{ entry.rank }}</strong><span class="fw-semibold">{{ entry.username }}</span><span>{{ entry.hours|round(2) }} hours</span></div>
        {% else %}<p class="small text-muted mb-0">No leaderboard data yet.</p>{% endfor %}
        <p class="small text-muted mt-3 mb-2">You are #{{ leaderboard.current_rank or '—' }} with {{ leaderboard.lifetime_hours|round(2) }} lifetime hours.</p>
        <a class="btn btn-outline-secondary btn-sm" href="{{ url_for('progress_view') }}">View leaderboard</a>
      </div>
    </section>
  </div>
</div>
{% endblock %}

