          <td class="fw-semibold">{{ item.student_name }}</td>
          <td>{{ item.prize_name }}</td>
          <td>Manual</td>
          <td>{{ item.redemption.redeemed_at.strftime('%b %d, %Y') }}</td>
          <td><form method="post" action="{{ url_for('fulfill_prize_redemption', redemption_id=item.redemption.redemption_id) }}"><button class="btn btn-primary btn-sm" type="submit">Mark fulfilled</button></form></td>
        </tr>
        {% endfor %}
        </tbody>
      </table>
    </div>
    {% else %}<p class="text-muted p-3 mb-0">No pending prize redemptions.</p>{% endif %}
  </section>
</div>

<div class="modal fade" id="rejectModal" tabindex="-1" aria-labelledby="rejectModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header"><h2 class="modal-title h5" id="rejectModalLabel">Reject submission</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div>
      <form id="rejectForm" method="post">
        <div class="modal-body">
          <p class="small text-muted">Enter the reason <span id="rejectStudentName"></span> needs to address.</p>
          <label class="visually-hidden" for="rejection_reason">Rejection reason</label>
          <textarea class="form-control" id="rejection_reason" name="rejection_reason" rows="4" placeholder="Enter the reason the student needs to address..." required></textarea>
        </div>
        <div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-admin-reject" type="submit">Confirm Reject</button></div>
      </form>
    </div>
  </div>
</div>
{% endblock %}

{% block subpage_scripts %}
