      document.getElementById("rejectForm").action = button.dataset.rejectUrl;
      document.getElementById("rejectStudentName").textContent = `for ${button.dataset.studentName}`;
      document.getElementById("rejection_reason").value = "";
    });
  });
</script>
{% endblock %}
"}

