            <a class="student-nav-link {{ 'active' if request.url.path.startswith('/app/volunteer-hours') }}" href="{{ url_for('volunteer_hours_view') }}">Submit hours</a>
            <a class="student-nav-link {{ 'active' if request.url.path.startswith('/app/progress') }}" href="{{ url_for('progress_view') }}">Leaderboard &amp; milestones</a>
            <a class="student-nav-link {{ 'active' if request.url.path.startswith('/app/prizes') }}" href="{{ url_for('prizes_view') }}">Prizes &amp; redemptions</a>
        </nav>
        <div class="student-user">
            <span class="student-badge-label {{ badge.color if badge else 'neutral' }}"><span class="badge-emblem {{ badge.color if badge else 'neutral' }}"><span class="material-symbols-outlined" aria-hidden="true">{{ badge.icon if badge else 'star_border' }}</span></span>{{ badge.name if badge else 'Badge' }}</span>
            <span class="student-badge">{{ user.username[:1]|upper }}</span>
            <span class="fw-semibold">{{ user.username }}</span>
            <a class="btn btn-outline-secondary btn-sm" href="{{ url_for('logout') }}">Sign out</a>
        </div>
    </header>

    <main class="student-main">
        {% for message in get_flashed_messages(request) %}
        <div class="alert alert-{{ message.type }}" role="alert">{{ message.message }}</div>
        {% endfor %}
        {% block subpage_content %}{% endblock %}
    </main>
</div>
