    font-size: 1.55rem;
  }

  .home-section {
    margin-bottom: 1.25rem;
  }

  .home-milestone {
    padding: 1.25rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .home-badge-panel {
    padding: 1.25rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .home-badge-icon {
    display: grid;
    place-items: center;
    min-height: 90px;
    margin-top: 1rem;
    background: #e8ebee;
  }

  .home-badge-icon .material-symbols-outlined {
    font-size: 3rem;
  }

  .home-badge-icon .badge-emblem {
    width: 4.5rem;
    height: 4.5rem;
  }

  .home-badge-icon .badge-emblem .material-symbols-outlined {
    font-size: 3rem;
  }

  .home-leaderboard-row {
    display: grid;
    grid-template-columns: 2.5rem 1fr auto;
    gap: 0.75rem;
    padding: 0.75rem 0;
    border-bottom: 1px solid #d8e0e9;
  }

  .home-leaderboard-row:last-child {
    border-bottom: 0;
  }

  .events-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .event-card {
    padding: 1rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .event-date {
    color: var(--brand-accent);
    font-size: 0.8rem;
    font-weight: 800;
    text-transform: uppercase;
  }

  @media (max-width: 1100px) {
    .home-layout {
      grid-template-columns: 1fr;
    }

    .home-intro-row {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 850px) {
    .home-stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 500px) {
    .home-stats {
      grid-template-columns: 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="home-intro-row">
<div class="home-heading">
  <h1 class="mb-1">Welcome back, {{ user.username }}</h1>
  <p class="text-muted mb-0">Your volunteer activity, rewards, and progress at a glance.</p>
</div>

<section class="wire-card">
  <div class="wire-card-header"><h2 class="h5 mb-0">Upcoming volunteer events</h2></div>
  <div class="p-3 events-grid">
    {% for event in upcoming_events %}
    <article class="event-card"><div class="event-date">{{ event.date }}</div><h3 class="h6 mt-2 mb-2">{{ event.name }}</h3><div class="small text-muted">{{ event.location }} · {{ event.hours }} hours available</div></article>
    {% endfor %}
  </div>
</section>
</div>

<div class="home-stats">
  <div class="home-stat"><span class="text-muted small">Lifetime hours</span><strong>{{ approved_hours|hours }} hours</strong><span class="small text-muted">Total approved volunteer hours</span></div>
  <div class="home-stat"><span class="text-muted small">Spendable balance</span><strong>{{ spendable_balance|hours }} hours</strong><span class="small text-muted">After redemptions</span></div>
  <div class="home-stat"><span class="text-muted small">Rank</span><strong>#{{ leaderboard.current_rank or '—' }}</strong><span class="small text-muted">Among {{ leaderboard.total_participants }} student volunteers</span></div>
  <div class="home-stat"><span class="text-muted small">Badges</span><strong>{{ progress.milestones|selectattr('achieved')|list|length }}/{{ progress.milestones|length }}</strong><span class="small text-muted">{{ badge.name }} milestone unlocked</span></div>
</div>

<div class="home-layout">
  <div>
    <section class="home-section home-milestone">
      <div class="d-flex justify-content-between align-items-center gap-2 mb-2">
        <h2 class="h5 mb-0">Next milestone: {{ next_milestone.title }}</h2>
        <strong>{{ progress.approved_hours|hours }} / {{ next_milestone.required_hours }} lifetime hours</strong>
      </div>
      <div class="progress" role="progressbar" aria-label="{{ next_milestone.title }} progress" aria-valuenow="{{ next_milestone.percent }}" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width: {{ next_milestone.percent }}%; background-color: var(--brand-accent);"></div></div>
      <p class="text-muted mb-0 mt-3">{{ next_milestone.remaining_hours|hours }} more approved hours to unlock {{ next_milestone.title }}. Redeeming prizes does not affect milestones.</p>
    </section>

    <section class="home-section wire-card">
      <div class="wire-card-header"><h2 class="h5 mb-0">Recent submissions</h2></div>
      <div class="table-responsive">
        <table class="table align-middle mb-0">
          <thead><tr><th>Event name</th><th>Date submitted</th><th>Hours</th><th>Status</th><th>Details</th></tr></thead>
          <tbody>
          {% for log in logs[:5] %}
          <tr><td>{{ log.event_name }}</td><td>{{ log.submitted_at.strftime('%b %d, %Y') }}</td><td>{{ log.hours|hours }}</td><td>{{ log.status|title }}</td><td><button class="btn btn-link btn-sm p-0 submission-details-button" type="button" data-bs-toggle="modal" data-bs-target="#submissionDetailsModal" data-event="{{ log.event_name }}" data-hours="{{ log.hours|hours }}" data-date="{{ log.event_date.strftime('%b %d, %Y') }}" data-submitted="{{ log.submitted_at.strftime('%b %d, %Y') }}" data-status="{{ log.status|title }}" data-info="{{ log.additional_info or '' }}" data-proof="{{ url_for('static', path=log.proof) }}" data-rejection="{{ log.rejection_reason or '' }}">View details</button></td></tr>
          {% else %}<tr><td colspan="5" class="text-muted">No submissions yet.</td></tr>{% endfor %}
          </tbody>
        </table>
      </div>
      <div class="small text-muted p-3 border-top">Pending and rejected hours are not included in your balance.</div>
    </section>
  </div>

  <div>
    <section class="home-section home-badge-panel">
      <h2 class="h5 mb-1">Latest badge</h2>
      <div class="text-uppercase text-muted small">{{ badge.name }} badge · {% if badge.name == 'No badge yet' %}locked{% else %}unlocked{% endif %}</div>
      <div class="home-badge-icon"><span class="badge-emblem {{ badge.color }}"><span class="material-symbols-outlined" aria-hidden="true">{{ badge.icon }}</span></span></div>
      {% if badge.reached_date %}<p class="text-muted small mt-3 mb-1">Reached {{ badge.reached_date.strftime('%b %d, %Y') }}.</p>{% endif %}
      <p class="small mb-0">Next: {{ next_milestone.title }} at {{ next_milestone.required_hours }} lifetime hours</p>
    </section>

    <section class="wire-card">
      <div class="wire-card-header"><h2 class="h5 mb-0">Top 3 volunteers</h2></div>
      <div class="p-3">
        {% for entry in leaderboard.entries[:3] %}
        <div class="home-leaderboard-row"><strong>#{{ entry.rank }}</strong><span class="fw-semibold">{{ entry.username }}</span><span>{{ entry.hours|hours }} hours</span></div>
        {% else %}<p class="small text-muted mb-0">No leaderboard data yet.</p>{% endfor %}
        <p class="small text-muted mt-3 mb-2">You are #{{ leaderboard.current_rank or '—' }} with {{ leaderboard.lifetime_hours|hours }} lifetime hours.</p>
        <a class="btn btn-outline-secondary btn-sm" href="{{ url_for('progress_view') }}">View leaderboard</a>
      </div>
    </section>
  </div>
</div>

<div class="modal fade" id="submissionDetailsModal" tabindex="-1" aria-labelledby="submissionDetailsLabel" aria-hidden="true">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header"><h2 class="modal-title h5" id="submissionDetailsLabel">Submission details</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div>
      <div class="modal-body">
        <h3 class="h5" id="detailsEvent"></h3>
        <dl class="row small mb-3"><dt class="col-5">Event date</dt><dd class="col-7" id="detailsDate"></dd><dt class="col-5">Submitted</dt><dd class="col-7" id="detailsSubmitted"></dd><dt class="col-5">Hours</dt><dd class="col-7" id="detailsHours"></dd><dt class="col-5">Status</dt><dd class="col-7" id="detailsStatus"></dd></dl>
        <div class="mb-3"><strong>Additional information</strong><p class="small text-muted mb-0" id="detailsInfo"></p></div>
        <div class="mb-3"><strong>Proof</strong><img class="img-fluid d-block mt-2" id="detailsProof" alt="Submitted proof"></div>
        <div class="alert alert-danger d-none mb-0" id="detailsRejection"><strong>Rejection reason</strong><div id="detailsRejectionText"></div></div>
      </div>
    </div>
  </div>
</div>
{% endblock %}

{% block subpage_scripts %}
<script>
  document.querySelectorAll(".submission-details-button").forEach(function (button) {
    button.addEventListener("click", function () {
      document.getElementById("detailsEvent").textContent = button.dataset.event;
      document.getElementById("detailsDate").textContent = button.dataset.date;
      document.getElementById("detailsSubmitted").textContent = button.dataset.submitted;
      document.getElementById("detailsHours").textContent = `${button.dataset.hours} hours`;
      document.getElementById("detailsStatus").textContent = button.dataset.status;
      document.getElementById("detailsInfo").textContent = button.dataset.info || "None provided.";
      document.getElementById("detailsProof").src = button.dataset.proof;
      const rejection = document.getElementById("detailsRejection");
      rejection.classList.toggle("d-none", !button.dataset.rejection);
      document.getElementById("detailsRejectionText").textContent = button.dataset.rejection;
    });
  });
</script>
{% endblock %}

{% extends "authenticated-base.html" %}
{% block title %}Volunteer Hours{% endblock %}

{% block additional_styles %}
<style>
  .workflow-heading {
    margin-bottom: 1.5rem;
  }

  .workflow-heading h1 {
    font-size: clamp(1.7rem, 3vw, 2.2rem);
    font-weight: 800;
  }

  .volunteer-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.7fr) minmax(280px, 0.8fr);
    gap: 1.25rem;
    align-items: start;
  }

  .wire-card {
    background: var(--brand-surface);
    border: 1px solid #b8c3cf;
    box-shadow: none;
  }

  .wire-card-header {
    padding: 1.15rem 1.25rem;
    border-bottom: 1px solid #d8e0e9;
  }

  .wire-card-body {
    padding: 1.25rem;
  }

  .proof-dropzone {
    display: block;
    padding: 1.5rem;
    border: 1px dashed #8da0b5;
    background: #f4f6f8;
    text-align: center;
    cursor: pointer;
  }

  .proof-dropzone:hover,
  .proof-dropzone:has(+ input:focus) {
    border-color: var(--brand-accent);
    background: color-mix(in srgb, var(--brand-accent) 10%, #f4f6f8);
  }

  .proof-preview {
    display: none;
    width: 100%;
    max-height: 180px;
    margin-top: 0.9rem;
    object-fit: contain;
    border: 1px solid #b8c3cf;
    background: #fff;
  }

  .pending-item {
    padding: 0.85rem 0;
    border-bottom: 1px solid #d8e0e9;
  }

  .pending-item:last-child {
    border-bottom: 0;
    padding-bottom: 0;
  }

  .status-text {
    font-size: 0.82rem;
    font-weight: 700;
  }

  @media (max-width: 900px) {
    .volunteer-layout {
      grid-template-columns: 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="workflow-heading">
  <h1 class="mb-1">Submit hours</h1>
  <p class="text-muted mb-0">Log completed volunteer work. Hours count toward your rewards once approved.</p>
</div>

<div class="volunteer-layout">
  <section id="submit-hours" class="wire-card">
    <div class="wire-card-header">
      <h2 class="h5 mb-1">New volunteer-hour submission</h2>
      <p class="text-muted small mb-0">Required fields are marked with <span class="required-mark">*</span></p>
    </div>
    <div class="wire-card-body">
      <form method="post" action="{{ request.url.path }}" enctype="multipart/form-data">
        <div class="row g-3">
          <div class="col-12">
            <label class="form-label" for="event_name">Event name <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_name" name="event_name" placeholder="Volunteer activity" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="hours">Hours <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="hours" name="hours" type="number" min="0.01" step="0.01" required>
          </div>
          <div class="col-md-6">
            <label class="form-label" for="event_date">Event date <span class="required-mark" aria-hidden="true">*</span></label>
            <input class="form-control" id="event_date" name="event_date" type="date" max="{{ today }}" required>
          </div>
          <div class="col-12">
            <label class="form-label" for="additional_info">Additional information <span class="text-muted">(optional)</span></label>
            <textarea class="form-control" id="additional_info" name="additional_info" rows="3" placeholder="Add any extra context, notes, or details about the activity."></textarea>
          </div>
          <div class="col-12">
            <label class="form-label" for="proof">Proof <span class="required-mark" aria-hidden="true">*</span></label>
            <label class="proof-dropzone" for="proof">
              <strong>Drop a file here or browse files</strong>
              <span class="d-block text-muted small mt-2">Photo or signed attendance sheet · JPG, PNG · Max 10 MB</span>
            </label>
            <input class="visually-hidden" id="proof" name="proof" type="file" accept="image/*" required>
            <img class="proof-preview" id="proof-preview" alt="Selected proof preview">
            <div class="text-muted small mt-2" id="proof-status">No image selected yet.</div>
          </div>
        </div>
        <div class="d-flex flex-wrap gap-2 mt-4">
          <button class="btn btn-primary" type="submit">Submit</button>
          <a class="btn btn-outline-secondary" href="{{ url_for('user_home_view') }}">Cancel</a>
        </div>
      </form>
    </div>
  </section>

  <aside class="d-grid gap-3">
    <section class="wire-card">
      <div class="wire-card-body">
        <h2 class="h6 mb-2">Tip: make your proof easy to verify</h2>
        <p class="small text-muted mb-0">Include your name, event date, and volunteered hours in a clear proof image.</p>
      </div>
    </section>

    <section class="wire-card">
      <div class="wire-card-header">
        <h2 class="h6 mb-1">Your pending submissions ({{ summary.pending|length }})</h2>
        <p class="small text-muted mb-0">{{ summary.pending_hours|hours }} hours awaiting approval</p>
      </div>
      <div class="wire-card-body">
        {% if summary.pending %}
        {% for log in summary.pending %}
        <div class="pending-item">
          <div class="fw-semibold">{{ log.event_name }}</div>
          <div class="small text-muted">{{ log.hours|hours }} hours · {{ log.event_date.strftime('%b %d, %Y') }}</div>
          <div class="status-text mt-1">Pending</div>
        </div>
        {% endfor %}
        {% else %}
        <p class="small text-muted mb-0">No pending submissions.</p>
        {% endif %}
        <p class="small text-muted border-top mt-3 pt-3 mb-0">Pending hours are not included in lifetime hours or balance.</p>
      </div>
    </section>

    <section class="wire-card">
      <div class="wire-card-header">
        <h2 class="h6 mb-0">Rejected submissions</h2>
      </div>
      <div class="wire-card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
          <span class="small text-muted">{{ summary.rejected|length }} rejection{{ '' if summary.rejected|length == 1 else 's' }}</span>
        </div>
        {% for log in summary.rejected %}
        <div class="pending-item">
          <div class="fw-semibold">{{ log.event_name }}</div>
          <div class="small text-muted">{{ log.hours|hours }} hours · {{ log.event_date.strftime('%b %d, %Y') }}</div>
          <div class="status-text text-danger mt-1">Rejected</div>
          {% if log.rejection_reason %}<div class="small text-danger mt-1"><strong>Why it was rejected:</strong> {{ log.rejection_reason }}</div>{% endif %}
        </div>
        {% endfor %}
        {% if not summary.rejected %}<p class="small text-muted mb-0">No rejected submissions.</p>{% endif %}
      </div>
    </section>
  </aside>
  </div>
{% endblock %}

{% block subpage_scripts %}
<script>
  const proofInput = document.getElementById("proof");
  const proofPreview = document.getElementById("proof-preview");
  const proofStatus = document.getElementById("proof-status");

  proofInput.addEventListener("change", function () {
    const file = proofInput.files[0];
    if (!file) {
      proofPreview.style.display = "none";
      proofPreview.removeAttribute("src");
      proofStatus.textContent = "No image selected yet.";
      return;
    }

    proofPreview.src = URL.createObjectURL(file);
    proofPreview.style.display = "block";
    proofStatus.textContent = `Selected: ${file.name}`;
  });
</script>
{% endblock %}

{% extends "authenticated-base.html" %}
{% block title %}Prizes and My Redemptions{% endblock %}

{% block additional_styles %}
<style>
  .prize-heading-row {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
  }

  .prize-heading {
    flex: 1;
  }

  .prize-heading h1 {
    font-size: clamp(1.7rem, 3vw, 2.2rem);
    font-weight: 800;
  }

  .prize-metrics {
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr;
    gap: 0.75rem;
    width: min(100%, 665px);
  }

  .prize-metric {
    padding: 0.75rem 1rem;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .prize-metric-balance {
    border: 2px solid var(--brand-ink);
    background: color-mix(in srgb, var(--brand-accent) 18%, #fff);
    padding: 1.15rem 1.25rem;
  }

  .prize-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1.25rem;
    margin-bottom: 1.25rem;
  }

  .prize-card {
    display: flex;
    flex-direction: column;
    border: 1px solid #aeb8c3;
    background: var(--brand-surface);
  }

  .prize-image {
    display: grid;
    place-items: center;
    min-height: 112px;
    margin: 1rem 1rem 0;
    background: #d9d9d9;
    color: #5c6167;
    font-size: 0.8rem;
    font-weight: 700;
  }

  .prize-image img {
    width: 100%;
    height: 112px;
    object-fit: cover;
  }

  .prize-content {
    display: flex;
    flex: 1;
    flex-direction: column;
    padding: 1rem;
  }

  .redemption-layout {
    display: block;
  }

  .redemption-history {
    width: 100%;
  }

  .redemption-header,
  .redemption-row {
    display: grid;
    grid-template-columns: 1.3fr 0.8fr 1fr 0.8fr;
    gap: 0.75rem;
    align-items: center;
  }

  .redemption-header {
    padding: 0.7rem 0.8rem;
    background: #e8ebee;
    border: 1px solid #c5cdd6;
    font-size: 0.78rem;
    font-weight: 800;
  }

  .redemption-row {
    padding: 0.8rem 0;
    margin-inline: 0.8rem;
    border-bottom: 1px solid #d8e0e9;
  }

  .redemption-row:last-child {
    border-bottom: 0;
  }

  .confirm-panel {
    border: 2px solid var(--brand-ink);
    background: var(--brand-surface);
  }

  .confirm-modal-header {
    border-bottom: 3px solid var(--brand-accent);
  }

  .confirm-prize-preview {
    width: 96px;
    height: 72px;
    object-fit: cover;
    border: 1px solid #aeb8c3;
  }

  @media (max-width: 1000px) {
    .prize-grid {
      grid-template-columns: 1fr;
    }

    .prize-heading-row {
      align-items: stretch;
      flex-direction: column;
    }

    .prize-metrics {
      width: 100%;
    }
  }

  @media (max-width: 650px) {
    .prize-metrics {
      grid-template-columns: 1fr;
    }

    .redemption-row {
      grid-template-columns: 1fr 1fr;
    }
  }
</style>
{% endblock %}

{% block subpage_content %}
<div class="prize-heading-row">
  <div class="prize-heading">
    <h1 class="mb-1">Prizes &amp; My Redemptions</h1>
    <p class="text-muted mb-0">Exchange your spendable hours for prizes.</p>
  </div>
  <div class="prize-metrics">
    <div class="prize-metric prize-metric-balance"><div class="small text-muted">Spendable balance</div><div class="h3 mb-0">{{ spendable_balance|hours }} hours</div></div>
    <div class="prize-metric"><div class="small text-muted">Prizes redeemed</div><div class="h4 mb-0">{{ redemptions|length }}</div></div>
    <div class="prize-metric"><div class="small text-muted">Hours redeemed</div><div class="h4 mb-0">{{ redeemed_hours|hours }}</div></div>
  </div>
</div>

<div class="prize-grid">
  {% for prize in prizes %}
  <article class="prize-card">
    <div class="prize-image">
      {% if prize.image_url %}<img src="{{ url_for('static', path=prize.image_url) }}" alt="{{ prize.name }}">{% else %}<span>Prize image</span>{% endif %}
    </div>
    <div class="prize-content">
      <h2 class="h5">{{ prize.name }}</h2>
      <div class="d-flex justify-content-between gap-2 mb-2"><strong>Cost: {{ prize.hours_cost|hours }} hours</strong><span>Stock: {{ prize.stock }} left</span></div>
      <div class="small text-muted mb-3">Delivery type: {{ prize.delivery_type|title }}</div>
      {% if prize.stock <= 0 %}
      <button class="btn btn-outline-secondary mt-auto" type="button" disabled>Out of stock</button>
      {% elif spendable_balance < prize.hours_cost %}
      <button class="btn btn-outline-secondary mt-auto" type="button" disabled>Not enough hours</button>
      {% else %}
      <button class="btn btn-primary mt-auto redeem-button" type="button" data-bs-toggle="modal" data-bs-target="#redemptionModal" data-prize-name="{{ prize.name }}" data-prize-cost="{{ prize.hours_cost|hours }}" data-balance-after="{{ [spendable_balance - prize.hours_cost, 0]|max|hours }}" data-prize-image="{{ url_for('static', path=prize.image_url) }}" data-redeem-url="{{ url_for('redeem_prize', prize_id=prize.prize_id) }}">Redeem</button>
      {% endif %}
    </div>
  </article>
  {% endfor %}
</div>

<div class="redemption-layout">
  <section class="wire-card redemption-history">
    <div class="wire-card-header"><h2 class="h5 mb-0">My redemption history</h2></div>
    <div class="p-3">
      {% if redemptions %}
      <div class="redemption-header"><span>Prize Name</span><span>Hours Cost</span><span>Date</span><span>Status</span></div>
      {% for row in redemption_rows %}
      <div class="redemption-row">
        <span class="fw-semibold">{{ row.prize_name }}</span>
        <span>{{ row.hours_cost|hours }} hours</span>
        <span>{{ row.redemption.redeemed_at.strftime('%b %d, %Y') }}</span>
        <span>{{ row.redemption.status|title }}{% if row.delivery_type == 'manual' %}<small class="d-block text-muted">Manual delivery</small>{% endif %}</span>
      </div>
      {% endfor %}
      <p class="small text-muted border-top mt-3 pt-3 mb-0">Pickup: Student Services, Mon-Fri, 9:00-17:00. Bring your student ID.</p>
      {% else %}<p class="small text-muted mb-0">No redemptions yet.</p>{% endif %}
      <p class="small text-muted border-top mt-3 pt-3 mb-0">Pending hours have already been deducted from your balance.</p>
    </div>
  </section>

</div>

<div class="modal fade" id="redemptionModal" tabindex="-1" aria-labelledby="redemptionModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header confirm-modal-header">
        <h2 class="modal-title h5" id="redemptionModalLabel">Confirm Redemption</h2>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
      </div>
      <div class="modal-body">
        <div class="d-flex gap-3 align-items-center mb-3">
          <img class="confirm-prize-preview" id="confirmPrizeImage" alt="">
          <div><h3 class="h6 mb-1" id="confirmPrizeName"></h3><p class="small text-muted mb-0" id="confirmPrizeCost"></p></div>
        </div>
        <p class="mb-2">Redeeming this prize will deduct the hours from your spendable balance.</p>
        <p class="fw-bold mb-2">Balance after redemption: <span id="confirmBalanceAfter"></span> hours</p>
        <p class="small text-muted mb-0">Manual prizes remain pending until an administrator fulfils them.</p>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button>
        <form id="redemptionForm" method="post"><button class="btn btn-primary" type="submit">Confirm redemption</button></form>
      </div>
    </div>
  </div>
</div>
{% endblock %}

{% block subpage_scripts %}
<script>
  document.querySelectorAll(".redeem-button").forEach(function (button) {
    button.addEventListener("click", function () {
      document.getElementById("confirmPrizeName").textContent = button.dataset.prizeName;
      document.getElementById("confirmPrizeCost").textContent = `${button.dataset.prizeCost} hours`;
      document.getElementById("confirmBalanceAfter").textContent = button.dataset.balanceAfter;
      document.getElementById("confirmPrizeImage").src = button.dataset.prizeImage;
      document.getElementById("confirmPrizeImage").alt = button.dataset.prizeName;
      document.getElementById("redemptionForm").action = button.dataset.redeemUrl;
    });
  });
</script>
{% endblock %}

