:root {
  /* Phase 5 theming: Guide overwrites these from docs/report.md preferences */
  --brand-name: "Apex Awards";
  --brand-bg: #071a36;
  --brand-surface: #ffffff;
  --brand-ink: #10233f;
  --brand-muted: #5a6d84;
  --brand-accent: #e7b83f;
  --brand-accent-2: #8ca9c9;
  --brand-sidebar: #0b2347;
  --brand-sidebar-text: #c7d6e8;
  --brand-font-display: "Manrope", "Segoe UI", sans-serif;
  --brand-font-body: "Manrope", "Segoe UI", sans-serif;
  --brand-radius: 0.45rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--brand-font-body);
  color: var(--brand-ink);
  background: var(--brand-bg);
}

.brand-wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.35em;
  font-family: var(--brand-font-display);
  font-weight: 800;
  letter-spacing: -0.04em;
}

.brand-wordmark::before {
  content: "★";
  color: var(--brand-accent);
  font-size: 0.62em;
  line-height: 1;
}

/* —— Public landing —— */
.landing {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  color: var(--brand-surface);
  background:
    linear-gradient(135deg, rgba(231, 184, 63, 0.12), transparent 36%),
    linear-gradient(180deg, #123664 0%, var(--brand-bg) 72%);
  position: relative;
  overflow: hidden;
}

.landing::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(
      -28deg,
      transparent,
      transparent 56px,
      rgba(255, 255, 255, 0.045) 56px,
      rgba(255, 255, 255, 0.045) 58px
    );
  pointer-events: none;
}

.landing-nav,
.landing-hero,
.landing-foot {
  position: relative;
  z-index: 1;
}

.landing-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem clamp(1.25rem, 4vw, 3rem);
}

.landing-nav .brand-wordmark {
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  color: var(--brand-surface);
  text-decoration: none;
}

.landing-nav-actions {
  display: flex;
  gap: 0.65rem;
  flex-wrap: wrap;
}

.landing-hero {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(2rem, 8vh, 5rem) clamp(1.25rem, 4vw, 3rem) 3rem;
  max-width: 42rem;
}

.landing-kicker {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--brand-accent);
  margin: 0 0 1rem;
}

.landing-hero .brand-wordmark {
  font-size: clamp(3rem, 9vw, 5.5rem);
  line-height: 0.95;
  margin: 0 0 1.25rem;
  color: var(--brand-surface);
}

.landing-lead {
  font-size: clamp(1.05rem, 2.2vw, 1.25rem);
  line-height: 1.55;
  color: color-mix(in srgb, var(--brand-surface) 82%, transparent);
  margin: 0 0 2rem;
  max-width: 28rem;
}

.landing-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.btn-landing {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.35rem;
  border-radius: 999px;
  font-weight: 600;
  text-decoration: none;
  border: 1.5px solid transparent;
  transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.btn-landing:hover {
  transform: translateY(-1px);
}

.btn-landing-primary {
  background: var(--brand-accent);
  color: var(--brand-ink);
}

.btn-landing-primary:hover {
  background: color-mix(in srgb, var(--brand-accent) 82%, #fff);
  color: var(--brand-ink);
}

.btn-landing-ghost {
  background: transparent;
  color: var(--brand-surface);
  border-color: color-mix(in srgb, var(--brand-surface) 45%, transparent);
}

.btn-landing-ghost:hover {
  border-color: var(--brand-surface);
  background: color-mix(in srgb, var(--brand-surface) 8%, transparent);
