{% extends "admin-base.html" %}
{% block title %}Admin Console{% endblock %}

{% block admin_styles %}
<style>
  .admin-heading-row {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.25rem;
  }

  .admin-actions {
    display: flex;
    gap: 0.5rem;
    align-items: end;
  }

  .admin-stat-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .admin-stat {
    padding: 1rem;
    border: 1px solid #aeb8c3;
    background: #fff;
  }

  .admin-stat strong {
    display: block;
    font-size: 1.45rem;
  }

  .admin-queues {
    display: grid;
    grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.95fr);
    gap: 1.25rem;
    align-items: start;
  }

  .admin-queue {
    min-width: 0;
    border: 1px solid #aeb8c3;
    background: #fff;
  }

  .admin-queue-header {
    padding: 1rem 1.15rem;
    border-bottom: 1px solid #c9d1d9;
  }

  .admin-table {
    width: 100%;
    margin: 0;
  }

  .admin-table th,
  .admin-table td {
    padding: 0.75rem;
    border-bottom: 1px solid #d8e0e9;
    vertical-align: middle;
  }

  .admin-table th {
    background: #e8ebee;
    color: #4e5964;
    font-size: 0.76rem;
    white-space: nowrap;
  }

  .admin-table tr:last-child td {
    border-bottom: 0;
  }

  .btn-admin-approve {
    background: #218739;
    border-color: #218739;
    color: #fff;
  }

  .btn-admin-approve:hover,
  .btn-admin-approve:focus {
    background: #176b2b;
    border-color: #176b2b;
    color: #fff;
  }

  .btn-admin-reject {
    background: #c93636;
    border-color: #c93636;
    color: #fff;
  }

  .btn-admin-reject:hover,
  .btn-admin-reject:focus {
    background: #9f2525;
    border-color: #9f2525;
    color: #fff;
  }

  @media (max-width: 1100px) {
    .admin-stat-grid,
    .admin-queues {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .admin-queues {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 650px) {
    .admin-heading-row {
      align-items: stretch;
      flex-direction: column;
    }

    .admin-stat-grid {
      grid-template-columns: 1fr;
    }
  }
</style>
